Controller result:
{"results": [{"id": "hp_doc_ecc4d4dd1201dde729e35b676f2e602f90911598c274d25a274b6c97e8844146", "title": "Lee Chapman", "text": "Lee Roy Chapman (born 5 December 1959) is an English former professional footballer who played as a striker from 1978 until 1996, in which he scored almost 200 first-team goals.", "score": 16.915}, {"id": "hp_doc_5e4b542e3de84a25a53b238b81af5b680a5f574c1fe414ac35af6f762b0eddc5", "title": "Roy Chapman", "text": "Roy Clifford Chapman (18 March 1934 – 21 March 1983) was an English professional footballer and manager, born in Birmingham. He was the father of former Arsenal and Leeds United striker Lee Chapman.", "score": 16.1744}, {"id": "hp_doc_177403d6775e1d96aede2095024a9dbd47f98a8812f14dadece651eff9ea9162", "title": "4 Runner", "text": "4 Runner was an American country music vocal group founded in 1993 by lead singer Craig Morris, baritone Billy Crittenden, tenor Lee Hilliard, and bass Jim Chapman. Signed to Polydor Records Nashville, the quartet released its self-titled debut album in 1995, It featured four charting singles on Hot Country Songs, the most successful being \"Cain's Blood\" at No. 26. Billy Simon took Crittenden's place just before a second album for A&M Records, which was not released despite producing a chart single, and the band broke up afterward. Chapman, Hilliard, and Morris reunited with third baritone singer Michael Lusk to release its next album, \"Getaway Car\", on the Fresh label before disbanding a second time.", "score": 10.6372}], "remaining_searches": 1}
